#nullable enable // autogenerated

using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Modifiers;
using Tools;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Contraptions
{
    [BuffDefinition(VanillaBuffNames.Contraption.fireworkDispenserEasterEgg)]
    public class FireworkDispenserEasterEggBuff : BuffDefinition
    {
        public FireworkDispenserEasterEggBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new Vector3Modifier(EngineEntityProps.DISPLAY_SCALE, NumberOperator.Multiply, new Vector3(1.333f, 1, 1)));
            AddModifier(new Vector3Modifier(VanillaEntityProps.SHADOW_SCALE, NumberOperator.Multiply, new Vector3(1.333f, 1, 1)));
        }
        public override void PostAdd(Buff buff)
        {
            base.PostAdd(buff);
            buff.SetProperty(PROP_TIMER, new FrameTimer(TIMEOUT));
            var entity = buff.GetEntity();
            entity?.Level.AddLoopSoundEntity(VanillaSoundID.songFoDeniseSample, entity.ID);
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var entity = buff.GetEntity();
            if (entity != null)
            {
                var timer = buff.GetProperty<FrameTimer>(PROP_TIMER);
                if (timer == null || timer.Expired)
                {
                    buff.Remove();
                    entity.Level.RemoveLoopSoundEntity(VanillaSoundID.songFoDeniseSample, entity.ID);
                }
                else
                {
                    timer.Run();
                }
            }
            else
            {
                buff.Remove();
            }
        }
        public const int TIMEOUT = 150;
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("timer");
    }
}
